/**
 * Allure API Service
 *
 * Queries Allure Docker Service API for test report statistics.
 * Allure endpoint: https://allure.docbits.com/allure-docker-service
 *
 * Used to fetch test results for service-based test grouping on /tests page.
 * Each microservice uploads test results to environment-specific Allure projects.
 *
 * Example project IDs:
 * - web-unit-tests-dev
 * - web-component-tests-stage
 * - playwright-critical-prod
 */

// Create a plain axios instance without authentication interceptors
// DO NOT use 'boot/axios' - it adds auth headers that trigger CORS failures
import axios from 'axios';
import { logger } from 'src/utils/logger';

// Create dedicated axios instance for Allure API (no auth, no interceptors)
const allureAxios = axios.create({
  baseURL: 'https://allure.docbits.com/allure-docker-service',
  timeout: 5000,
  headers: {
    'Content-Type': 'application/json',
  },
});

/**
 * Allure report structure returned by /projects/{id}/reports/latest/widgets/summary.json endpoint
 */
export interface AllureReport {
  reportName?: string; // Optional - returned by summary.json
  statistic: {
    passed: number;
    failed: number;
    broken: number;
    skipped: number;
    unknown: number;
    total: number;
  };
  time: {
    start: number;
    stop: number;
    duration: number;
    minDuration: number;
    maxDuration: number;
    sumDuration: number;
  };
  testRuns?: any[]; // Optional - returned by summary.json
}

/**
 * Label from Allure test case (epic, feature, story, severity, custom labels)
 */
export interface AllureLabel {
  name: string;
  value: string;
}

/**
 * Individual test case result from status-chart.json endpoint
 */
export interface AllureTestCase {
  uid: string;
  name: string;
  time: {
    start: number;
    stop: number;
    duration: number;
  };
  status: 'passed' | 'failed' | 'broken' | 'skipped' | 'unknown';
  severity: string;
  // Optional fields from detailed endpoint
  fullName?: string;
  description?: string;
  statusMessage?: string; // Error message for failed tests
  statusTrace?: string; // Full stack trace for failed tests
  labels?: AllureLabel[]; // Allure labels (epic, feature, story, severity, custom)
}

/**
 * Allure severity levels, ordered most → least severe.
 * `unknown` is our own bucket for test cases with a missing/unrecognized severity.
 */
export const ALLURE_SEVERITIES = [
  'blocker',
  'critical',
  'normal',
  'minor',
  'trivial',
  'unknown',
] as const;

export type AllureSeverity = (typeof ALLURE_SEVERITIES)[number];

/**
 * Severities that count as "critical" on the tests overview table.
 * `blocker` is more severe than `critical` in Allure, so both are included.
 */
export const CRITICAL_SEVERITIES: AllureSeverity[] = ['blocker', 'critical'];

/**
 * Status counts for a single severity bucket.
 * `failed` intentionally merges Allure's `failed` + `broken` — both mean "not green".
 */
export interface SeverityStatusCounts {
  total: number;
  passed: number;
  failed: number;
  skipped: number;
}

/**
 * Severity × status matrix for one Allure project.
 */
export interface ProjectSeverityBreakdown {
  projectId: string;
  total: number;
  bySeverity: Record<AllureSeverity, SeverityStatusCounts>;
}

/** Empty severity matrix — every bucket zeroed. */
export function emptySeverityMatrix(): Record<AllureSeverity, SeverityStatusCounts> {
  return ALLURE_SEVERITIES.reduce(
    (acc, severity) => {
      acc[severity] = { total: 0, passed: 0, failed: 0, skipped: 0 };
      return acc;
    },
    {} as Record<AllureSeverity, SeverityStatusCounts>
  );
}

/** Normalize an arbitrary Allure severity string into a known bucket. */
export function normalizeSeverity(severity: string | undefined): AllureSeverity {
  const value = (severity || '').toLowerCase() as AllureSeverity;
  return ALLURE_SEVERITIES.includes(value) ? value : 'unknown';
}

/**
 * Fold a list of test cases into a severity × status matrix.
 *
 * Pure function — exported separately from the service so it can be unit tested
 * without touching the network.
 */
export function aggregateSeverityBreakdown(
  projectId: string,
  tests: AllureTestCase[]
): ProjectSeverityBreakdown {
  const bySeverity = emptySeverityMatrix();

  for (const test of tests) {
    const bucket = bySeverity[normalizeSeverity(test.severity)];
    bucket.total += 1;

    if (test.status === 'failed' || test.status === 'broken') {
      bucket.failed += 1;
    } else if (test.status === 'skipped') {
      bucket.skipped += 1;
    } else if (test.status === 'passed') {
      bucket.passed += 1;
    }
    // `unknown` status counts toward total only
  }

  return { projectId, total: tests.length, bySeverity };
}

/**
 * Service for interacting with Allure Docker Service API
 *
 * Provides methods to:
 * - Fetch latest test report for a project
 * - Check if all tests are passing
 * - Query test statistics
 */
export class AllureApiService {
  private readonly baseUrl = 'https://allure.docbits.com/allure-docker-service';

  /**
   * Get latest report statistics for a project
   * Returns pass/fail counts and overall status
   *
   * @param projectId - Environment-specific project ID (e.g., 'web-unit-tests-dev')
   * @returns AllureReport object or null if project not found
   *
   * @example
   * const report = await allureApiService.getLatestReport('web-unit-tests-dev');
   * console.log(`Total tests: ${report.statistic.total}`);
   * console.log(`Failed: ${report.statistic.failed}`);
   */
  async getLatestReport(projectId: string): Promise<AllureReport | null> {
    try {
      logger.debug(`[AllureApi] Fetching latest report for project: ${projectId}`);

      // Correct endpoint: /projects/{id}/reports/latest/widgets/summary.json
      // This returns the actual test statistics, not just project metadata
      // Using allureAxios (plain axios instance) to avoid auth headers that trigger CORS
      const response = await allureAxios.get(
        `/projects/${projectId}/reports/latest/widgets/summary.json`
      );

      if (response.data) {
        // summary.json returns data directly (not wrapped in data.data)
        logger.debug(`[AllureApi] Successfully fetched report for ${projectId}`, {
          total: response.data.statistic.total,
          failed: response.data.statistic.failed,
          broken: response.data.statistic.broken,
        });
        return response.data;
      }

      logger.warn(`[AllureApi] No report data returned for ${projectId}`);
      return null;
    } catch (error: any) {
      // Project might not exist or no reports yet - this is expected for new projects
      if (error.response?.status === 404) {
        logger.debug(`[AllureApi] Project not found: ${projectId} (404)`);
      } else if (error.code === 'ECONNABORTED') {
        logger.warn(`[AllureApi] Timeout fetching report for ${projectId}`);
      } else {
        logger.warn(`[AllureApi] Error fetching report for ${projectId}:`, error.message);
      }
      return null;
    }
  }

  /**
   * Check if all tests passed for a project
   * Returns true only if no failures or broken tests
   *
   * @param projectId - Environment-specific project ID
   * @returns true if all tests passed, false otherwise
   *
   * @example
   * const allPassing = await allureApiService.areAllTestsPassing('web-unit-tests-dev');
   * if (allPassing) {
   *   console.log('✅ All tests passed!');
   * }
   */
  async areAllTestsPassing(projectId: string): Promise<boolean> {
    const report = await this.getLatestReport(projectId);
    if (!report) {
      logger.debug(`[AllureApi] No report available for ${projectId}, assuming not passing`);
      return false;
    }

    const { failed, broken } = report.statistic;
    const allPassing = failed === 0 && broken === 0;

    logger.debug(`[AllureApi] Test status for ${projectId}:`, {
      allPassing,
      failed,
      broken,
      total: report.statistic.total,
    });

    return allPassing;
  }

  /**
   * Get test statistics summary for a project
   * Convenience method that returns key metrics
   *
   * @param projectId - Environment-specific project ID
   * @returns Statistics object or null
   */
  async getStatistics(projectId: string) {
    const report = await this.getLatestReport(projectId);
    if (!report) return null;

    return {
      total: report.statistic.total,
      passed: report.statistic.passed,
      failed: report.statistic.failed,
      broken: report.statistic.broken,
      skipped: report.statistic.skipped,
      allPassing: report.statistic.failed === 0 && report.statistic.broken === 0,
      lastRunAt: new Date(report.time.stop),
      duration: report.time.duration,
    };
  }

  /**
   * Get detailed test case results for a project
   * Returns individual test results with pass/fail status
   *
   * @param projectId - Environment-specific project ID
   * @param filterStatus - Optional status to filter by ('failed', 'broken', 'passed', 'skipped')
   * @returns Array of test cases or null if project not found
   *
   * @example
   * const tests = await allureApiService.getDetailedTestResults('docflow-dev');
   * const failedTests = tests.filter(t => t.status === 'failed');
   */
  async getDetailedTestResults(
    projectId: string,
    filterStatus?: 'failed' | 'broken' | 'passed' | 'skipped',
    options?: { timeoutMs?: number }
  ): Promise<AllureTestCase[] | null> {
    try {
      logger.debug(`[AllureApi] Fetching detailed test results for project: ${projectId}`);

      // Endpoint: /projects/{id}/reports/latest/widgets/status-chart.json
      // Returns array of all individual test cases with full details
      const response = await allureAxios.get(
        `/projects/${projectId}/reports/latest/widgets/status-chart.json`,
        options?.timeoutMs ? { timeout: options.timeoutMs } : undefined
      );

      if (response.data && Array.isArray(response.data)) {
        const tests: AllureTestCase[] = response.data;

        logger.debug(`[AllureApi] Fetched ${tests.length} test cases for ${projectId}`);

        // Filter by status if requested
        if (filterStatus) {
          const filtered = tests.filter((test) => test.status === filterStatus);
          logger.debug(
            `[AllureApi] Filtered to ${filtered.length} tests with status: ${filterStatus}`
          );
          return filtered;
        }

        return tests;
      }

      logger.warn(`[AllureApi] No test case data returned for ${projectId}`);
      return null;
    } catch (error: any) {
      if (error.response?.status === 404) {
        logger.debug(`[AllureApi] Test cases not found for ${projectId} (404)`);
      } else if (error.code === 'ECONNABORTED') {
        logger.warn(`[AllureApi] Timeout fetching test cases for ${projectId}`);
      } else {
        logger.warn(`[AllureApi] Error fetching test cases for ${projectId}:`, error.message);
      }
      return null;
    }
  }

  /**
   * Get detailed information for a specific test case
   * Includes error messages and stack traces for failed tests
   *
   * @param projectId - Environment-specific project ID
   * @param testUid - Unique identifier for the test case
   * @returns Detailed test case information or null if not found
   *
   * @example
   * const details = await allureApiService.getTestCaseDetails('docflow-dev', 'e7fbdd230ab2e4b');
   * console.log(details.statusMessage); // Error message
   */
  async getTestCaseDetails(
    projectId: string,
    testUid: string
  ): Promise<Partial<AllureTestCase> | null> {
    try {
      logger.debug(`[AllureApi] Fetching test case details: ${projectId}/${testUid}`);

      // Endpoint: /projects/{id}/reports/latest/data/test-cases/{uid}.json
      const response = await allureAxios.get(
        `/projects/${projectId}/reports/latest/data/test-cases/${testUid}.json`
      );

      if (response.data) {
        const details = {
          uid: response.data.uid,
          name: response.data.name,
          fullName: response.data.fullName,
          description: response.data.description,
          statusMessage: response.data.statusMessage,
          statusTrace: response.data.statusTrace,
          labels: response.data.labels || [],
        };

        logger.debug(`[AllureApi] Fetched detailed info for ${testUid}`, {
          labelsCount: details.labels.length,
        });
        return details;
      }

      return null;
    } catch (error: any) {
      if (error.response?.status === 404) {
        logger.debug(`[AllureApi] Test case details not found for ${testUid} (404)`);
      } else {
        logger.warn(`[AllureApi] Error fetching test case details:`, error.message);
      }
      return null;
    }
  }

  /**
   * Get the severity × status breakdown for a project's latest report.
   *
   * Allure exposes no per-severity summary widget, so this derives the matrix
   * from the full test case list (status-chart.json). That payload is large for
   * big suites (~200 KB gzipped for 5k tests), which is why callers should load
   * it lazily rather than as part of the initial page render.
   *
   * @param projectId - Environment-specific project ID
   * @returns Severity breakdown, or null when the project has no report
   *
   * @example
   * const breakdown = await allureApiService.getSeverityBreakdown('doc2-api-e2e-dev');
   * console.log(breakdown.bySeverity.critical.failed); // 45
   */
  async getSeverityBreakdown(projectId: string): Promise<ProjectSeverityBreakdown | null> {
    // Larger timeout than the default: status-chart.json is orders of magnitude
    // bigger than summary.json and routinely exceeds the 5s default on big suites.
    const tests = await this.getDetailedTestResults(projectId, undefined, { timeoutMs: 30000 });
    if (!tests) {
      return null;
    }

    const breakdown = aggregateSeverityBreakdown(projectId, tests);

    logger.debug(`[AllureApi] Severity breakdown for ${projectId}:`, {
      total: breakdown.total,
      criticalTotal: breakdown.bySeverity.critical.total,
      criticalFailed: breakdown.bySeverity.critical.failed,
      blockerFailed: breakdown.bySeverity.blocker.failed,
    });

    return breakdown;
  }

  /**
   * Get Allure UI URL for a project
   * Returns direct link to view test results in Allure UI
   *
   * @param projectId - Environment-specific project ID
   * @returns Full URL to Allure UI for this project
   */
  getProjectUrl(projectId: string): string {
    return `${this.baseUrl}-ui/projects/${projectId}`;
  }
}

// Export singleton instance
export const allureApiService = new AllureApiService();
