/**
 * Auth Tests Aggregator Service
 *
 * Fetches test status from a single consolidated Allure project for the Auth service.
 * Queries `auth-{env}` project and returns simple pass/fail status.
 *
 * Used by /tests page to display current test status for the Auth service.
 *
 * Note: All test types (unit, integration, e2e) are now uploaded to a single
 * consolidated project `auth-{env}` instead of separate category projects.
 */

import { allureApiService } from '../allure';
import { logger } from 'src/utils/logger';
import type { TestCategoryStatus } from './webTestsAggregator.service';

/**
 * Overall Auth service test status
 */
export interface AuthTestsStatus {
  service: 'auth';
  displayName: string;
  environment: string; // 'dev', 'stage', 'prod', etc.
  allPassing: boolean;
  categories: TestCategoryStatus[];
  totalTests: number;
  totalFailed: number;
  lastUpdated: Date;
}

/**
 * Service that fetches test results from the consolidated Auth Allure project
 */
export class AuthTestsAggregatorService {
  /**
   * Get test status for Auth service in current environment
   *
   * Queries the single consolidated Allure project `auth-{env}` and returns
   * pass/fail status for display on /tests page.
   *
   * @param environment - Current environment (dev, stage, prod, etc.)
   * @returns AuthTestsStatus object with test status
   *
   * @example
   * const status = await authTestsAggregatorService.getAuthTestsStatus('dev');
   * console.log(`All passing: ${status.allPassing}`);
   * console.log(`Total failed: ${status.totalFailed} of ${status.totalTests}`);
   */
  async getAuthTestsStatus(environment: string): Promise<AuthTestsStatus> {
    logger.info(`[AuthTestsAggregator] Fetching test status for environment: ${environment}`);

    // Single consolidated project for all auth tests
    const projectId = `auth-${environment}`;
    const categories: TestCategoryStatus[] = [];

    try {
      const report = await allureApiService.getLatestReport(projectId);

      const hasData = report !== null && report.statistic.total > 0;

      // Create a single "All Tests" category representing the consolidated project
      const status: TestCategoryStatus = {
        name: 'all',
        displayName: 'All Tests',
        projectId,
        allPassing: hasData
          ? report.statistic.failed + report.statistic.broken === 0
          : false,
        totalTests: report?.statistic.total || 0,
        failedTests: report ? report.statistic.failed + report.statistic.broken : 0,
        lastRunAt: report ? new Date(report.time.stop) : null,
        hasData,
      };

      logger.debug(`[AuthTestsAggregator] All Tests:`, {
        hasData: status.hasData,
        allPassing: status.allPassing,
        totalTests: status.totalTests,
        failedTests: status.failedTests,
      });

      categories.push(status);

      logger.info(`[AuthTestsAggregator] Status for ${environment}:`, {
        allPassing: status.allPassing,
        totalTests: status.totalTests,
        totalFailed: status.failedTests,
      });

      return {
        service: 'auth',
        displayName: 'Auth Service',
        environment,
        allPassing: status.allPassing,
        categories,
        totalTests: status.totalTests,
        totalFailed: status.failedTests,
        lastUpdated: new Date(),
      };
    } catch (error) {
      logger.error(`[AuthTestsAggregator] Error fetching test status:`, error);

      // Return status with hasData: false on error
      const emptyStatus: TestCategoryStatus = {
        name: 'all',
        displayName: 'All Tests',
        projectId,
        allPassing: false,
        totalTests: 0,
        failedTests: 0,
        lastRunAt: null,
        hasData: false,
      };

      categories.push(emptyStatus);

      return {
        service: 'auth',
        displayName: 'Auth Service',
        environment,
        allPassing: false,
        categories,
        totalTests: 0,
        totalFailed: 0,
        lastUpdated: new Date(),
      };
    }
  }

  /**
   * Alias for getAuthTestsStatus to maintain consistency with generic services
   */
  async getTestsStatus(environment: string): Promise<AuthTestsStatus> {
    return this.getAuthTestsStatus(environment);
  }

  /**
   * Get status for a specific test category
   *
   * @param environment - Current environment
   * @param categoryName - Category name (now only 'all' is supported)
   * @returns TestCategoryStatus or null if not found
   */
  async getCategoryStatus(
    environment: string,
    categoryName: string
  ): Promise<TestCategoryStatus | null> {
    const fullStatus = await this.getAuthTestsStatus(environment);
    return fullStatus.categories.find((cat) => cat.name === categoryName) || null;
  }
}

// Export singleton instance
export const authTestsAggregatorService = new AuthTestsAggregatorService();
