/**
 * DocFlow Tests Aggregator Service
 *
 * Aggregates test status from Allure projects for the DocFlow service.
 * Queries environment-specific projects and returns simple pass/fail status.
 *
 * Used by /tests page to display current test status for the DocFlow service.
 *
 * Test categories:
 * - All Tests (comprehensive test suite)
 */

import { allureApiService } from '../allure';
import { logger } from 'src/utils/logger';
import type { TestCategoryStatus, WebTestsStatus } from './webTestsAggregator.service';

/**
 * DocFlow service test status
 */
export interface DocFlowTestsStatus extends Omit<WebTestsStatus, 'service'> {
  service: 'docflow';
}

/**
 * Service that aggregates test results from DocFlow test categories
 */
export class DocFlowTestsAggregatorService {
  /**
   * Get test status for DocFlow service in current environment
   *
   * Queries environment-specific Allure project and returns
   * aggregated pass/fail status for display on /tests page.
   *
   * @param environment - Current environment (dev, stage, prod, etc.)
   * @returns DocFlowTestsStatus object with all test category statuses
   *
   * @example
   * const status = await docflowTestsAggregatorService.getDocFlowTestsStatus('dev');
   * console.log(`All passing: ${status.allPassing}`);
   * console.log(`Total failed: ${status.totalFailed} of ${status.totalTests}`);
   */
  async getDocFlowTestsStatus(environment: string): Promise<DocFlowTestsStatus> {
    logger.info(`[DocFlowTestsAggregator] Fetching test status for environment: ${environment}`);

    const categories: TestCategoryStatus[] = [];

    // DocFlow has a single comprehensive test suite
    const testCategories = [
      {
        name: 'all',
        displayName: 'All Tests',
        projectId: `docflow-${environment}`,
      },
    ];

    // Check status for each category in parallel for better performance
    const categoryPromises = testCategories.map(async (category) => {
      try {
        const report = await allureApiService.getLatestReport(category.projectId);

        const status: TestCategoryStatus = {
          name: category.name,
          displayName: category.displayName,
          projectId: category.projectId,
          allPassing: report
            ? report.statistic.failed + report.statistic.broken === 0
            : false,
          totalTests: report?.statistic.total || 0,
          failedTests: report ? report.statistic.failed + report.statistic.broken : 0,
          lastRunAt: report ? new Date(report.time.stop) : null,
        };

        logger.debug(`[DocFlowTestsAggregator] ${category.displayName}:`, {
          allPassing: status.allPassing,
          totalTests: status.totalTests,
          failedTests: status.failedTests,
        });

        return status;
      } catch (error) {
        logger.error(`[DocFlowTestsAggregator] Error fetching ${category.displayName}:`, error);

        // Return failed status on error
        return {
          name: category.name,
          displayName: category.displayName,
          projectId: category.projectId,
          allPassing: false,
          totalTests: 0,
          failedTests: 0,
          lastRunAt: null,
        };
      }
    });

    // Wait for all category statuses
    const resolvedCategories = await Promise.all(categoryPromises);
    categories.push(...resolvedCategories);

    // Calculate overall status
    const allPassing = categories.every((cat) => cat.allPassing);
    const totalTests = categories.reduce((sum, cat) => sum + cat.totalTests, 0);
    const totalFailed = categories.reduce((sum, cat) => sum + cat.failedTests, 0);

    logger.info(`[DocFlowTestsAggregator] Aggregated status for ${environment}:`, {
      allPassing,
      totalTests,
      totalFailed,
      categoriesChecked: categories.length,
    });

    return {
      service: 'docflow',
      displayName: 'DocFlow',
      environment,
      allPassing,
      categories,
      totalTests,
      totalFailed,
      lastUpdated: new Date(),
    };
  }

  /**
   * Get status for a specific test category
   *
   * @param environment - Current environment
   * @param categoryName - Category name (e.g., 'all')
   * @returns TestCategoryStatus or null if not found
   */
  async getCategoryStatus(
    environment: string,
    categoryName: string
  ): Promise<TestCategoryStatus | null> {
    const fullStatus = await this.getDocFlowTestsStatus(environment);
    return fullStatus.categories.find((cat) => cat.name === categoryName) || null;
  }
}

// Export singleton instance
export const docflowTestsAggregatorService = new DocFlowTestsAggregatorService();
