/**
 * Critical Tests Prometheus Service (DOCB-13953)
 *
 * All critical-test data for all services comes from a SINGLE Prometheus
 * query. A Prometheus selector matches several metric families at once, so one
 * HTTP request returns every metric for every service as one flat vector — no
 * per-service and no per-metric fan-out. The flat array is grouped client-side
 * by service + environment + track, then dispatched on __name__.
 *
 * Architecture decision (mirrors sentinelLogApi.service.ts):
 *   Base URL: https://prometheus.docbits.com — fixed, NOT env-prefixed.
 *   A single Prometheus instance serves every environment; the environment is
 *   a metric LABEL, so it is filtered inside the query rather than in the host.
 *
 * Metric schema — `docbits_deploy_blocking_*`, every family a gauge carrying
 * service + environment + track, and all but _run_info also repo:
 *   *_status{service,environment,track,repo}              1 = allowed to deploy, 0 = blocked
 *   *_configured{service,environment,track,repo}          1 = gate wired up, 0 = nothing gates it
 *   *_timestamp_seconds{service,environment,track,repo}   unix seconds, when the producer pushed
 *   *_tests_total{service,environment,track,repo,result}  result = passed|failed
 *   *_run_info{service,environment,track,run_id,commit,image_tag,blocked_by}
 *                                                        always 1; the labels carry the payload
 *
 * `track` is `vesta` or `nova` — the release line, derived centrally by the
 * collector from the ref. DocBits ships two lines through ONE set of
 * environments, so `environment` alone does not identify a deployment: the
 * `-nova` segment is stripped out of it and reported as `track` instead, which
 * is why `dev-nova` arrives as environment="dev", track="nova" rather than as a
 * sixth environment. See TRACK_LABEL and AGGREGATION_LABELS for what that means
 * for reading it, and DEFAULT_TRACK for the samples pushed before it existed.
 *
 * WHY A WINDOW QUERY AND NOT AN INSTANT QUERY
 * -------------------------------------------
 * The producer pushes these metrics to a Pushgateway, which holds each group in
 * memory and re-serves it on every scrape. A group the gateway stops holding —
 * pod rescheduled, group deleted — stops producing samples instantly, and an
 * instant query then returns nothing for a service whose history Prometheus
 * still has in full. On 2026-08-12 a gateway reschedule dropped every group at
 * once: samples stopped dead and this table went blank while the data was
 * intact. So the freshness of these series measures the GATEWAY, never the
 * service.
 *
 * Every read therefore asks for a window — last_over_time(…[7d:5m]) — and the
 * age of a verdict comes from *_timestamp_seconds instead. A verdict without
 * its age is not a status: with a window query the series no longer disappears,
 * which makes age the only thing separating "green two minutes ago" from "green
 * four days ago". Age is therefore always carried and always rendered — but as
 * a plain fact beside the verdict, never as a verdict of its own. See
 * gateState() for why no age threshold exists.
 *
 * The read contract is DevOps/.github/docs/DEPLOY_GATE_METRICS.md; keep this
 * file in step with it.
 */

import axios from 'axios';
import { logger } from 'src/utils/logger';

// ============================================================================
// Constants
// ============================================================================

const PROMETHEUS_URL = 'https://prometheus.docbits.com';

/**
 * How far back a read looks, and at what resolution.
 *
 * 7d covers the realistic gap between two pipeline runs of a quiet repo and
 * stays well inside the 30d Prometheus retention. Declared once and used by
 * every query built here, so widening the window is a one-line change.
 */
export const METRIC_WINDOW = '7d';
const METRIC_WINDOW_STEP = '5m';

/**
 * The metric families this file dispatches on, named explicitly rather than
 * matched with `_.+`.
 *
 * Two reasons. The suite_* family is about four fifths of the series and is not
 * consumed, and over a window that payload only grows. And naming the families
 * is what lets AGGREGATION_LABELS below name every label that has to survive.
 *
 * `configured` is load-bearing, not decoration: a service with no
 * deployment-blocking tests deliberately publishes NO _status series at all,
 * rather than faking a green verdict, so the fleet must be enumerated from
 * _configured. ideas-service is in exactly that state and vanishes from the
 * table if this family is dropped.
 */
const CONSUMED_METRICS = ['status', 'configured', 'timestamp_seconds', 'run_info', 'tests_total'];

/**
 * THESE TRACKS ARE BRANCH LINES — NOT THE APP'S RELEASE CHANNELS
 * -------------------------------------------------------------
 * `vesta` and `nova` are the values the CI collector stamps on every series,
 * derived from the ref it ran on: branch `dev` — and `stage`, `sandbox`, `demo`,
 * `prod` — pushes track="vesta"; branch `dev-nova` pushes track="nova". They
 * name a BRANCH LINE and nothing else.
 *
 * `src/utils/release-names.ts` uses the same two proper nouns for the product's
 * release CHANNELS. Before DEVO-135 the two mappings ran in OPPOSITE
 * directions (branch `dev` was "Nova" to the product's old `latest` channel
 * but "vesta" to this collector) — that inversion is what this whole comment
 * block used to warn against reconciling. DEVO-135 renamed the channel enum
 * itself to `vesta`/`nova`, so the two now agree on the STRING VALUE.
 *
 * They still are not the same AXIS, though: a track is a branch line — every
 * org deployed on `dev` (whatever their individual release_channel) reports
 * track="vesta" here, because the CI collector stamps it from the ref it ran
 * on, not from any org's channel. Rendering a bare "VESTA"/"NOVA" would still
 * read as "this org's channel", which it isn't — hence trackLabel() naming the
 * branch line instead of the bare track value. See "THE TRACK TOGGLE IS
 * TRANSITIONAL" below for why the two axes aren't unified yet.
 *
 * THE TRACK TOGGLE IS TRANSITIONAL
 * --------------------------------
 * A user-selectable track is not the intended end state. The frontend will
 * eventually route the two lines separately — mirroring the deployment twice —
 * and each board will show only its own line, derived automatically, exactly as
 * `environment` is already derived from APP_VUE_STAGE and deliberately not
 * user-selectable. The input for that already exists: a company's channel comes
 * from /v2/users/me/organisations (`release_channel`, see
 * src/sdk/auth/models/meOrganisationItem.ts), is read by getCurrentChannel() in
 * src/pages/api-base-url.ts, and is surfaced in Settings → Company → Release
 * Channel (src/pages/Settings/Components/Company/ReleaseChannel.vue).
 *
 * That derivation is nevertheless BLOCKED today, and not by the naming (DEVO-135
 * fixed the naming): the product and the metrics still split on different axes.
 * The product splits by per-org channel within ONE environment — `nova` builds
 * the /nova/ bundle from a per-env `nova`/`nova-stage`/... branch, `vesta`
 * builds the root bundle from that same environment's normal branch (`dev`,
 * `stage`, ...). The metrics split by branch line across environments — `dev`
 * is vesta, `dev-nova` is nova. Every org on `dev` is thus built from a
 * non-`-nova` branch and resolves to track="vesta" regardless of its own
 * release_channel: deriving the track from a company's release channel today
 * would render two IDENTICAL boards. And `dev-nova`, the only source of
 * track="nova", feeds no per-org channel deployment at all — it's a separate,
 * full environment, not the source of the /nova/ bundle above.
 *
 * The prerequisite is that the deployed lines and the branch lines become the
 * same axis: that the /nova/ bundle and the root bundle are built from the two
 * branches the collector labels (i.e. `dev`/`dev-nova` directly, not a third
 * per-env `nova` branch). Until then the toggle stays, because it is the only
 * way to see that the nova line exists at all.
 */
const TRACK_LABEL = 'track';

/**
 * The two branch lines, in the order they are offered.
 *
 * VESTA is the line that ships today (`dev`, `stage`, `sandbox`, `demo`,
 * `prod`); NOVA is the `-nova` twin of each. Both build the same services into
 * the same environments, so a verdict is only identified by all three of
 * service + environment + track.
 */
export const RELEASE_TRACKS = ['vesta', 'nova'] as const;
export type ReleaseTrack = (typeof RELEASE_TRACKS)[number];

/**
 * What each line appends to an environment's branch name. VESTA deploys the
 * plain environment branch, NOVA its `-nova` twin.
 */
const TRACK_BRANCH_SUFFIX: Record<ReleaseTrack, string> = { vesta: '', nova: '-nova' };

/**
 * The branch line a track means, in one environment: `dev` / `dev-nova` on the
 * dev deployment, `stage` / `stage-nova` on stage.
 *
 * Falls back to the dev line when no environment is given, so a caller without
 * one still gets an unambiguous name rather than a bare track value.
 */
export function trackBranchLine(track: ReleaseTrack, environment?: string): string {
  return `${environment || 'dev'}${TRACK_BRANCH_SUFFIX[track]}`;
}

/**
 * How a track is named in the UI — `VESTA (dev)`, `NOVA (dev-nova)`.
 *
 * The parenthesised branch is not decoration: it is the only part of the label
 * that is unambiguous. "VESTA" alone means the other line in this same app —
 * Settings → Company → Release Channel calls the `frozen` channel Vesta and the
 * `latest` channel Nova, the inverse of these values. Naming the branch line
 * says which of the two a reader is looking at without having to know that.
 */
export function trackLabel(track: ReleaseTrack, environment?: string): string {
  return `${track.toUpperCase()} (${trackBranchLine(track, environment)})`;
}

/**
 * What a series with no `track` label is taken to mean.
 *
 * `track` joined the metric schema — and the Pushgateway grouping key — after
 * every service had already been reporting for weeks, and Prometheus keeps 30
 * days while this file reads 7. Those older samples are not noise: they are the
 * only thing many services have until their next pipeline run, because a recent
 * gateway restart cleared most groups.
 *
 * They are read as VESTA rather than filtered out, which is both the safe and
 * the factually correct choice. Correct, because every push that predates the
 * label came off `dev`/`stage`/`prod` — NOVA had no reporting pipeline at all.
 * Safe, because the alternative — a `track!=""` matcher — would make every
 * service that has not re-run since the change DISAPPEAR from the board, and a
 * service silently missing is worse than a service shown under the line it
 * actually deployed on.
 */
export const DEFAULT_TRACK: ReleaseTrack = 'vesta';

/**
 * Matchers that keep the result to real services in real environments.
 *
 * The `environment` matcher drops pushes from PR check runs — `270/merge`,
 * `feat/DOCB-42` — by excluding any environment name containing a slash. No
 * real environment name does and every branch ref does, so the filter needs no
 * maintenance as new ones appear. PR runs no longer push at all, but the ones
 * that already did stay for the retention window, and one of them is held
 * permanently fresh by the gateway.
 *
 * `service!~"poc-.*"` drops the proof-of-concept groups from the original
 * spike. A window query needs this where an instant query did not: those
 * gateway groups were deleted, so they are invisible to an instant query, but
 * five of them are still inside 7d.
 */
const REAL_SERIES_MATCHERS = ['environment!~".*/.*"', 'service!~"poc-.*"'];

/**
 * The labels the aggregation keeps. Everything not listed — `pod`, `instance`,
 * `container`, `endpoint`, `namespace`, `job` — is scrape-target metadata.
 *
 * `pod` is the one that matters. honorLabels preserves the pusher's labels, but
 * the scrape still attaches the gateway pod, so every gateway reschedule starts
 * a SECOND series per group, identical except for `pod`; over a window both are
 * returned. The aggregation must sit INSIDE the subquery, as it does below,
 * because each evaluation step then sees only the pod that was live at that
 * step. Aggregating outside the window instead mixes a dead pod's last value
 * with a live one's, and `max` would report green where the newest push was red.
 *
 * `__name__` is in the list on purpose. An aggregation drops the metric name
 * unless `by` names it, and `by` is the only form that can keep it — `without`
 * drops it unconditionally. Without the name nothing downstream can tell a
 * status from a timestamp.
 *
 * `track` is in the list for a harder reason, and it is the one entry here that
 * must never be "simplified" away. An aggregation keeps only what it groups by,
 * so dropping `track` does not merely lose a label: it merges the VESTA and NOVA
 * verdicts of one service into a SINGLE series, and `max` then returns the
 * greener of the two. A red NOVA gate would hide behind a green VESTA one and
 * the board would report that a blocked deployment was allowed — the exact
 * false-green this metric family exists to make impossible. Two release lines
 * deploy the same services into the same environments, so service +
 * environment does not identify a deployment; only service + environment +
 * track does.
 */
const AGGREGATION_LABELS = [
  '__name__',
  'service',
  'environment',
  TRACK_LABEL,
  'repo',
  'result',
  'run_id',
  'commit',
  'image_tag',
];

/**
 * Only the current metric family is read.
 *
 * The gate originally published under `docbits_critical_tests_*`; CI renamed it
 * to `docbits_deploy_blocking_*` and the old family stopped reporting on
 * 2026-08-10. Matching both was free for an instant query, because a retired
 * family simply returns nothing. Over a window it is not free: the retired
 * family comes back for as long as it is in retention, carrying the `service`
 * spellings it used at the time — `importemail-service`, `ocr`, `fulltext`,
 * `import-ftp-service`. Those resolve to the same display names as the current
 * labels, so the table would grow a second, permanently stale row for services
 * that are reporting normally. Reading one family is what keeps one service to
 * one row. metricSuffix() still normalizes the old names, so a payload
 * containing them is parsed correctly if one ever appears.
 *
 * @param environment - when given, filtered server-side via a label matcher
 * @param track - when given, restricts the read to one release line
 */
function seriesSelector(environment?: string, track?: ReleaseTrack): string {
  const matchers = [
    `__name__=~"docbits_deploy_blocking_(${CONSUMED_METRICS.join('|')})"`,
    ...REAL_SERIES_MATCHERS,
    ...(environment ? [`environment="${environment}"`] : []),
    ...(track ? [trackMatcher(track)] : []),
  ];
  return `{${matchers.join(',')}}`;
}

/**
 * Match one release line, including the samples pushed before `track` existed.
 *
 * An absent label is the empty string to a matcher, so `track="vesta"` would
 * exclude every pre-track series — see DEFAULT_TRACK for why that is the one
 * outcome to avoid. `track=~"vesta|"` is anchored by Prometheus as
 * `^(?:vesta|)$` and therefore matches both the label and its absence, which
 * makes reading VESTA server-side safe. NOVA needs no such alternative: no
 * pre-track sample can belong to a line that was not reporting yet.
 *
 * The page does not use this — it reads both lines in one request so it can
 * report which lines report at all — but a Grafana panel or a manual curl for a
 * single line should build the matcher here rather than by hand.
 */
function trackMatcher(track: ReleaseTrack): string {
  return track === DEFAULT_TRACK
    ? `${TRACK_LABEL}=~"${track}|"`
    : `${TRACK_LABEL}="${track}"`;
}

/** The bare selector with no environment filter. Handy for a manual curl. */
export const CRITICAL_TESTS_SELECTOR = seriesSelector();

/**
 * The one query every read of these metrics issues.
 *
 * Every call site — with and without an environment, with and without a track —
 * goes through here, so the window, the filters and the aggregation cannot drift
 * apart between them.
 */
export function buildCriticalStatusQuery(environment?: string, track?: ReleaseTrack): string {
  const selector = seriesSelector(environment, track);
  const aggregated = `max by (${AGGREGATION_LABELS.join(', ')}) (${selector})`;
  return `last_over_time(${aggregated}[${METRIC_WINDOW}:${METRIC_WINDOW_STEP}])`;
}

/**
 * Prometheus adds labels of its own (job, instance, and under Thanos possibly
 * receive/replica/tenant_id). Series are keyed on service + environment + track
 * only — never on these.
 *
 * `track` has to be part of the key for the same reason it has to survive the
 * aggregation: the fold below is a Map, so a key that cannot tell VESTA from
 * NOVA is last-writer-wins between two different deployments' results, and
 * Prometheus does not order its result. One of the two verdicts would simply
 * vanish, chosen at random.
 */
const GROUPING_LABELS = ['service', 'environment', TRACK_LABEL] as const;

// Plain axios instance: Prometheus is unauthenticated and the app's interceptors
// would attach auth headers that turn the preflight into a CORS failure.
const prometheusAxios = axios.create({
  baseURL: PROMETHEUS_URL,
  timeout: 20000,
  headers: { Accept: 'application/json' },
});

// ============================================================================
// Response types
// ============================================================================

export interface PromVectorResponse {
  status: 'success' | 'error';
  data: {
    resultType: 'vector';
    result: Array<{ metric: Record<string, string>; value: [number, string] }>;
  };
}

/** One service's critical-test gate verdict in one environment, on one track. */
export interface ServiceCriticalStatus {
  service: string;
  environment: string;
  /**
   * Release line this verdict belongs to — `vesta` or `nova`. Never empty: a
   * series pushed before the label existed reads as DEFAULT_TRACK.
   */
  track: string;
  passed: boolean;
  /**
   * When the producer pushed this verdict, or the epoch when no
   * *_timestamp_seconds series exists.
   *
   * The verdict's age, and the only source of it. Rendered next to the verdict
   * on every row and never folded into it: several services deploy about once a
   * week by design, so age says how current a verdict is and nothing about
   * whether it is good. See gateState().
   */
  finishedAt: Date;
  counts: { passed: number; failed: number; skipped: number };
  runId?: string;
  commit?: string;
  imageTag?: string;
  // --- extras beyond the ticket's model, needed to render honestly ---
  /** Source repository, e.g. DocBits_DocNet */
  repo?: string;
  /** Gate wired up in CI. False when *_configured reports 0. */
  configured: boolean;
  /** True when a *_status series exists at all. */
  hasStatus: boolean;
  /** Total tests counted across every result bucket. */
  totalTests: number;
  /**
   * False for placeholder rows added from the known-service registry — the
   * service exists in the app but Prometheus has no gate series for it at all.
   */
  hasMetrics: boolean;
}

/**
 * Rendered state of a card. Deliberately more granular than pass/fail: a gate
 * that reports success while having run zero critical tests is not a genuine
 * pass, and a service that publishes nothing is neither a pass nor a failure.
 *
 * Age is NOT one of these. It is reported alongside, not as a state — see
 * gateState().
 */
export type CriticalGateState =
  | 'failing'
  | 'passing'
  | 'no-tests'
  | 'not-configured'
  | 'no-metrics';

// ============================================================================
// Pure helpers (unit tested)
// ============================================================================

/**
 * Strip either metric-family prefix so both families dispatch identically.
 * `docbits_deploy_blocking_tests_total` and `docbits_critical_tests_total`
 * both reduce to `total`.
 */
export function metricSuffix(metricName: string): string {
  return metricName
    .replace(/^docbits_critical_tests_/, '')
    .replace(/^docbits_deploy_blocking_/, '')
    .replace(/^tests_total$/, 'total');
}

/**
 * The release line a series belongs to, with a missing label resolved.
 *
 * Every caller must go through here rather than reading `metric.track`, so that
 * a pre-track series and the same service's track-bearing series agree on their
 * line and therefore fold onto ONE row instead of two — see DEFAULT_TRACK.
 */
export function metricTrack(metric: Record<string, string>): string {
  return metric[TRACK_LABEL] || DEFAULT_TRACK;
}

/**
 * Group key — service + environment + track, ignoring infrastructure labels.
 *
 * `track` resolves through metricTrack() rather than being read raw, so a
 * service reporting both before and after the label landed keys onto one row
 * instead of growing a duplicate that differs only by having no track.
 */
export function seriesKey(metric: Record<string, string>): string {
  // Joined on an escaped NUL rather than a raw one: a literal control byte in
  // the source makes the file read as binary to grep/rg and other tooling.
  return GROUPING_LABELS.map((label) =>
    label === TRACK_LABEL ? metricTrack(metric) : (metric[label] ?? '')
  ).join('\u0000');
}

/**
 * True when `candidate` is a later run than `current`.
 *
 * GitHub run ids increase monotonically, so the largest is the most recent run.
 * A non-numeric id never wins against a numeric one, and never loses to one.
 */
function isNewerRun(candidate: string | undefined, current: string): boolean {
  if (candidate === undefined) return false;
  const next = Number(candidate);
  if (Number.isNaN(next)) return false;
  const previous = Number(current);
  if (Number.isNaN(previous)) return true;
  return next > previous;
}

function emptyStatus(metric: Record<string, string>): ServiceCriticalStatus {
  return {
    service: metric.service ?? 'unknown',
    environment: metric.environment ?? 'unknown',
    // A series pushed before `track` existed is VESTA, not 'unknown' and not a
    // row to be dropped — see DEFAULT_TRACK.
    track: metricTrack(metric),
    passed: false,
    finishedAt: new Date(0),
    counts: { passed: 0, failed: 0, skipped: 0 },
    configured: true,
    hasStatus: false,
    totalTests: 0,
    hasMetrics: true,
  };
}

/**
 * Services whose series are still inside the retention window but which will
 * never report a verdict again, so their row is noise rather than information.
 *
 * `fulltext-ai` became a single shared GPU deployment in May 2026 and its entry
 * was removed from DevOps/services/registry.yaml at the same time. Its `dev`
 * pipeline now fails at the first job with "Repo 'DocBits_Fulltext_AI' not found
 * in registry" and it has not deployed from `dev` since 2026-05-05, so the grey
 * "no gates" row it produces describes a pipeline that cannot run rather than a
 * service awaiting tests.
 *
 * This is NOT the place for a service that merely has no gate yet —
 * `ideas-service` reports configured=0 today and keeps its row, because that is
 * a true statement about a live pipeline and it has a real gate landing.
 */
const RETIRED_SERVICES = new Set(['fulltext-ai']);

/**
 * Which schema revision pushed a series: 1 once the collector labelled the
 * release line, 0 for everything pushed before it.
 *
 * This orders the two, which is what makes reading a missing `track` as VESTA
 * safe. `track` joined the Pushgateway GROUPING KEY, so every group pushed
 * before the change is keyed on a tuple no producer will ever write again:
 * nothing overwrites it, the gateway has no TTL, and it is re-served on every
 * scrape — so it keeps reporting the verdict it held on the day of the change,
 * indefinitely. Both it and the service's real series now fold onto the same
 * VESTA row, and the pre-track one is older BY CONSTRUCTION: the schema changed
 * at a point in time and no push after it omits the label.
 */
function schemaGeneration(metric: Record<string, string>): number {
  return metric[TRACK_LABEL] ? 1 : 0;
}

/**
 * Fold the flat Prometheus vector into one entry per service + environment +
 * track.
 *
 * Takes no clock: nothing here compares a timestamp against "now". The verdict's
 * age is derived where it is displayed, so it stays live between the five-minute
 * refreshes rather than being frozen at fold time.
 *
 * @param result - the `data.result` array as returned by buildCriticalStatusQuery
 */
export function groupCriticalStatuses(
  result: PromVectorResponse['data']['result']
): ServiceCriticalStatus[] {
  const byKey = new Map<string, ServiceCriticalStatus>();

  // Drop retired services before they ever become a row. Filtering here rather
  // than in the query keeps the PromQL readable and the reason documented, and
  // it applies to every consumer of this grouping.
  const samples = result.filter(
    ({ metric }) => !RETIRED_SERVICES.has((metric.service ?? '').toLowerCase())
  );

  // Where a row has both a pre-track and a track-bearing series, the
  // track-bearing one is the whole truth and the other must not contribute a
  // single field. Not just the ones with an ordering guard below — `status`,
  // `configured` and the counts have no timestamp to order them by, so without
  // this they would be last-writer-wins over an unordered Prometheus result,
  // and a stale green could overwrite a fresh red. Resolving the generation per
  // key up front makes that independent of the order the series arrive in.
  const newestGeneration = new Map<string, number>();
  for (const { metric } of samples) {
    const key = seriesKey(metric);
    const generation = schemaGeneration(metric);
    if (generation > (newestGeneration.get(key) ?? -1)) {
      newestGeneration.set(key, generation);
    }
  }

  const entryFor = (metric: Record<string, string>): ServiceCriticalStatus => {
    const key = seriesKey(metric);
    let entry = byKey.get(key);
    if (!entry) {
      entry = emptyStatus(metric);
      byKey.set(key, entry);
    }
    if (metric.repo) {
      entry.repo = metric.repo;
    }
    return entry;
  };

  for (const { metric, value } of samples) {
    if (schemaGeneration(metric) < (newestGeneration.get(seriesKey(metric)) ?? 0)) {
      continue;
    }

    const entry = entryFor(metric);
    // Prometheus always returns the sample value as a STRING — never assume numeric.
    const num = Number(value[1]);
    if (Number.isNaN(num)) {
      continue;
    }

    switch (metricSuffix(metric.__name__ ?? '')) {
      case 'status':
        entry.passed = num === 1;
        entry.hasStatus = true;
        break;
      case 'timestamp_seconds': {
        // A window can hand back more than one timestamp series for a service:
        // a gateway pod duplicate the aggregation did not collapse, or a `repo`
        // label that changed. The newest push is the one that describes the
        // current verdict, so an older duplicate must never overwrite it and
        // report a live service as older than it is.
        const finishedAtMs = num * 1000;
        if (finishedAtMs < entry.finishedAt.getTime()) break;
        entry.finishedAt = new Date(finishedAtMs);
        break;
      }
      case 'total':
        if (metric.result && metric.result in entry.counts) {
          entry.counts[metric.result as keyof ServiceCriticalStatus['counts']] = num;
        }
        break;
      case 'run_info':
        // run_id is a LABEL, so a new run is a new series rather than a new
        // value on an existing one, and a window returns every run it covers —
        // doc2-api had four inside 7d when this was written. The sample
        // timestamps are all the query time and cannot order them, so order on
        // the run id. Taking whichever series happened to arrive last would put
        // a days-old commit and build number next to a fresh verdict.
        if (entry.runId === undefined || isNewerRun(metric.run_id, entry.runId)) {
          entry.runId = metric.run_id;
          entry.commit = metric.commit;
          entry.imageTag = metric.image_tag;
        }
        break;
      case 'configured':
        entry.configured = num === 1;
        break;
      default:
        break;
    }
  }

  for (const entry of byKey.values()) {
    entry.totalTests = entry.counts.passed + entry.counts.failed + entry.counts.skipped;
  }

  // One service can legitimately hold two rows now — one per track — so `track`
  // breaks the tie and keeps the order deterministic.
  return [...byKey.values()].sort(
    (a, b) => a.service.localeCompare(b.service) || a.track.localeCompare(b.track)
  );
}

/** The rows of one release line. */
export function statusesForTrack(
  statuses: ServiceCriticalStatus[],
  track: string
): ServiceCriticalStatus[] {
  return statuses.filter((entry) => entry.track === track);
}

/**
 * How many services actually report on each track.
 *
 * Drives the track switch, and is the honest answer to "is NOVA reporting yet?"
 * — a zero is not a failure, it is a line whose pipelines do not publish a gate
 * verdict yet. Counts only rows Prometheus returned; placeholders are excluded
 * because a placeholder is the absence of a report, not one.
 */
export function trackReportCounts(
  statuses: ServiceCriticalStatus[]
): Record<ReleaseTrack, number> {
  const counts = { vesta: 0, nova: 0 } as Record<ReleaseTrack, number>;
  for (const entry of statuses) {
    if (entry.hasMetrics && entry.track in counts) {
      counts[entry.track as ReleaseTrack] += 1;
    }
  }
  return counts;
}

/**
 * Classify a gate for display.
 *
 * Order matters: an unconfigured gate is not a pass, and a gate that ran no
 * critical tests is not a pass either (the CI template treats pytest exit code 5
 * — "no tests collected" — as success).
 *
 * AGE IS NOT A STATE, DELIBERATELY
 * --------------------------------
 * This used to return 'stale' for a verdict older than 24h, ahead of the pass
 * check, so a green gate from two days ago rendered as a warning. That is wrong
 * for this fleet: several services legitimately deploy about once a week, so the
 * board reported normal operation as a fault and taught its readers to discount
 * it. A green verdict from six days ago is a green verdict. The age is reported
 * beside it, neutrally, and the "Reported" column sorts by it.
 *
 * No larger threshold replaces the old one, because ANY fixed threshold is wrong
 * for a fleet with mixed release cadences — a bigger number would only move which
 * services it libels. Age has to be judged against a service's own cadence, and
 * this board does not know that.
 *
 * The original reason for the harsh treatment is covered elsewhere now. 'stale'
 * was introduced because `operator` showed a green verdict beside 4 failures from
 * the retired Allure-era schema; schemaGeneration() disqualifies pre-schema rows
 * outright, so a superseded verdict no longer reaches this function at all.
 */
export function gateState(status: ServiceCriticalStatus): CriticalGateState {
  if (!status.hasMetrics) return 'no-metrics';
  if (!status.configured || !status.hasStatus) return 'not-configured';
  if (!status.passed) return 'failing';
  if (status.totalTests === 0) return 'no-tests';
  return 'passing';
}

/**
 * Gate states from "read this first" to "carries no information" — both the
 * board's default grouping and the order the Gate status column sorts by.
 *
 * A red gate outranks everything. Then the two states that reported something but
 * settled nothing: a green verdict with no tests behind it, and a service
 * declaring that nothing gates its deployment. Then the genuine passes. Rows with
 * no series at all come last — they are placeholders this app invents from its own
 * registry rather than anything a service said, they outnumber the reporting
 * services today, and a board that opens on ten grey rows buries the ones that
 * mean something.
 */
export const GATE_ORDER: readonly CriticalGateState[] = [
  'failing',
  'no-tests',
  'not-configured',
  'passing',
  'no-metrics',
];

export function gateRank(state: CriticalGateState): number {
  return GATE_ORDER.indexOf(state);
}

/**
 * The board's default order: attention first, then by how much each gate covers.
 *
 * Within a group, rows run by blocking test-case count descending — doc2-api's
 * ~14,300 at the top, ocr-service's 1 at the bottom — then by display name, so
 * the order is stable when counts tie.
 *
 * THE COUNT IS NOT A QUALITY RANKING. It is how many test cases can stop that
 * service's deployment, and nothing else. A thin gate is explicitly fine:
 * ocr-service reporting 1 case is not worse than doc2-api reporting 14,296, it
 * simply gates less, and services grow their gates over time. The count orders
 * the board only because it is the one magnitude this board has — read it as "how
 * much is covered", never as "how good".
 *
 * Attention rank comes FIRST, ahead of the count, because a pure count sort would
 * file a blocked service with a thin gate below thousands of passing cases, and a
 * board that hides a red row defeats its own purpose.
 *
 * This is the DEFAULT order only. The table renders rows as given while no column
 * is sorted (`pagination.sortBy: null`), and any user-sortable column takes over
 * the moment its header is clicked.
 */
export function sortForBoard(statuses: ServiceCriticalStatus[]): ServiceCriticalStatus[] {
  return [...statuses].sort(
    (a, b) =>
      gateRank(gateState(a)) - gateRank(gateState(b)) ||
      b.totalTests - a.totalTests ||
      serviceDisplayName(a.service).localeCompare(serviceDisplayName(b.service))
  );
}

/** Deep link to the GitHub Actions run that produced the metric. */
export function runUrl(status: ServiceCriticalStatus): string | null {
  if (!status.runId || !status.repo) return null;
  return `https://github.com/FELLOWPRO/${status.repo}/actions/runs/${status.runId}`;
}

/**
 * CI service labels do not match the service keys used in the web app
 * (DOCB-13956). Map what we know; fall back to a prettified label so a newly
 * onboarded service still renders sensibly instead of disappearing.
 *
 * A missing entry does not just cost a nice name — it splits a service into two
 * rows. Without a `webKey` the metric row cannot be matched to the placeholder
 * built from the app's own registry, so the service appears twice: once under a
 * prettified CI label with real numbers, and once as "no gate metric". That is
 * what "Doc2 Api" beside an empty "API Service" was.
 *
 * The keys here are the `service` label as CI emits it. Those come from the
 * `name` field of DevOps/services/registry.yaml, so the authoritative list is
 * that file, NOT this app's service keys — several differ (`doc2-api` vs `api`,
 * `ftp-import` vs `import-ftp`). Verify a new label against a live push
 * before adding it:
 *   {__name__="docbits_deploy_blocking_configured"}  on prometheus.docbits.com
 */
const SERVICE_LABEL_MAP: Record<string, { displayName: string; webKey?: string }> = {
  docflow: { displayName: 'DocFlow', webKey: 'docflow' },
  barcode: { displayName: 'Barcode Service', webKey: 'barcode' },
  docnet: { displayName: 'DocNet', webKey: 'docnet' },
  pomatch: { displayName: 'PO Matching', webKey: 'po-match' },
  'pomatch-service': { displayName: 'PO Matching', webKey: 'po-match' },
  ocr: { displayName: 'OCR Service', webKey: 'ocr' },
  importemail: { displayName: 'Email Import', webKey: 'email-import' },
  'importemail-service': { displayName: 'Email Import', webKey: 'email-import' },
  'import-ftp': { displayName: 'Import FTP', webKey: 'import-ftp' },
  'import-ftp-service': { displayName: 'Import FTP', webKey: 'import-ftp' },
  operator: { displayName: 'DOCOperator', webKey: 'docoperator' },
  docoperator: { displayName: 'DOCOperator', webKey: 'docoperator' },
  autoaccounting: { displayName: 'Auto Accounting', webKey: 'auto-accounting' },
  fulltext: { displayName: 'Fulltext Search', webKey: 'fulltext' },
  'fulltext-service': { displayName: 'Fulltext Search', webKey: 'fulltext' },
  extraction: { displayName: 'Extraction Service', webKey: 'extraction' },
  auth: { displayName: 'Auth Service', webKey: 'auth' },
  api: { displayName: 'API Service', webKey: 'api' },
  web: { displayName: 'Web Application', webKey: 'web' },
  watchdog: { displayName: 'WatchDog Service', webKey: 'watchdog' },
  'ideas-service': { displayName: 'Ideas Service' },

  // The registry names CI actually pushes, where they differ from the short key
  // above. Each was confirmed against a live series on prometheus.docbits.com.
  'doc2-api': { displayName: 'API Service', webKey: 'api' },
  'ocr-service': { displayName: 'OCR Service', webKey: 'ocr' },
  'barcode-service': { displayName: 'Barcode Service', webKey: 'barcode' },
  'auth-service': { displayName: 'Auth Service', webKey: 'auth' },
  'extraction-service': { displayName: 'Extraction Service', webKey: 'extraction' },
  'ftp-import': { displayName: 'Import FTP', webKey: 'import-ftp' },
  // This app itself. CI labels it `doc2app` — the name SERVICE_NAME, the
  // DO_APP_ID_* variables and envs/doc2app.env all use — while the app's own
  // service registry calls it `web`. Without this alias the real verdict would
  // render as a second row named "Doc2app" beside the `web` placeholder, which
  // is the duplicate this map exists to prevent.
  doc2app: { displayName: 'Web Application', webKey: 'web' },

  // Web-app service keys as aliases, so placeholder rows built from the app's
  // own service registry resolve to the same display names as CI labels.
  'po-match': { displayName: 'PO Matching', webKey: 'po-match' },
  'email-import': { displayName: 'Email Import', webKey: 'email-import' },
  'auto-accounting': { displayName: 'Auto Accounting', webKey: 'auto-accounting' },
};

export function serviceDisplayName(label: string): string {
  const mapped = SERVICE_LABEL_MAP[label.toLowerCase()];
  if (mapped) return mapped.displayName;
  return label
    .replace(/[-_]/g, ' ')
    .replace(/\b\w/g, (character) => character.toUpperCase());
}

/** Web-app service key for deep linking into /tests/:serviceName, when one exists. */
export function serviceWebKey(label: string): string | null {
  return SERVICE_LABEL_MAP[label.toLowerCase()]?.webKey ?? null;
}

/**
 * Add a placeholder row for every known service that Prometheus reports nothing
 * for, so the table lists the whole estate rather than only the services whose
 * CI gate happens to be wired up.
 *
 * Coverage is still partial (DOCB-13956), so a placeholder is not a defect.
 * Reporting as of 2026-08-13: doc2-api, docnet, ocr-service, email-import and
 * auto-accounting push real numbers; operator and DocFlow have the reporter
 * merged but last pushed before the counts existed; auth-service,
 * fulltext-service, ftp-import and extraction-service are not wired up yet;
 * ideas-service reports `configured=0` because nothing gates its deployment,
 * which is a verdict of its own and not the same thing as a placeholder.
 * DocBits_Web reports under the CI label `doc2app`: its `version & deploy` job
 * is gated by the `tests` job, whose ten continue-on-error: false checks are the
 * gate. Its Playwright suite is not part of it (DOCB-13416) and so contributes
 * no metrics.
 * All of those must read as "no gate metric", never as absent.
 *
 * ONE TRACK AT A TIME — the caller's obligation
 * ---------------------------------------------
 * Coverage is keyed on `service` alone, because a placeholder answers "does the
 * app know about a service Prometheus is silent about?" and that question has no
 * environment or track in it. Which means `statuses` must already be narrowed to
 * a single release line, or the answer is wrong in the one direction that
 * matters: a service reporting on VESTA and not on NOVA would count as covered,
 * no placeholder would be added, and the missing NOVA verdict — the finding —
 * would silently disappear instead of showing up as "no gate metric".
 *
 * @param statuses - grouped Prometheus results, ALREADY narrowed to one track
 * @param knownServices - service keys from the app's own registry
 * @param environment - selected environment, or '' when showing all
 * @param track - the release line these rows belong to; placeholders inherit it
 */
export function mergeWithKnownServices(
  statuses: ServiceCriticalStatus[],
  knownServices: string[],
  environment: string,
  track: ReleaseTrack = DEFAULT_TRACK
): ServiceCriticalStatus[] {
  const covered = new Set(
    statuses.map((entry) => serviceWebKey(entry.service) ?? entry.service.toLowerCase())
  );

  const placeholders: ServiceCriticalStatus[] = knownServices
    .filter((key) => !covered.has(key.toLowerCase()))
    .map((key) => ({
      service: key,
      environment: environment || 'any',
      track,
      passed: false,
      finishedAt: new Date(0),
      counts: { passed: 0, failed: 0, skipped: 0 },
      configured: false,
      hasStatus: false,
      totalTests: 0,
      hasMetrics: false,
    }));

  // Returned in the board's default order rather than alphabetically: the table
  // renders rows as given until a column header is clicked, so this is what a
  // reader sees first. See sortForBoard().
  return sortForBoard([...statuses, ...placeholders]);
}

// ============================================================================
// Service
// ============================================================================

export class CriticalTestsPrometheusService {
  private readonly logPrefix = '[CriticalTestsPrometheus]';

  /**
   * One request returns every metric for every service on BOTH release lines,
   * over a window rather than at an instant, so a service that has not reported
   * since the gateway last lost its groups is still returned — with its age, not
   * as missing.
   *
   * Reading both tracks in one request is deliberate: it is what lets a consumer
   * say which lines report at all, and switching between them costs no round
   * trip. Pass `track` only to read one line in isolation.
   *
   * @param environment - when given, filtered server-side via the label matcher
   * @param track - when given, restricts the read to one release line
   */
  async getCriticalStatuses(
    environment?: string,
    track?: ReleaseTrack
  ): Promise<ServiceCriticalStatus[]> {
    const query = buildCriticalStatusQuery(environment, track);

    logger.info(`${this.logPrefix} Querying Prometheus`, {
      environment: environment ?? 'all',
      track: track ?? 'all',
      window: METRIC_WINDOW,
    });

    const response = await prometheusAxios.get<PromVectorResponse>('/api/v1/query', {
      params: { query },
    });

    const body = response.data;
    if (body?.status !== 'success') {
      throw new Error('Prometheus query failed');
    }

    const statuses = groupCriticalStatuses(body.data.result);

    logger.info(`${this.logPrefix} Grouped ${body.data.result.length} series`, {
      rows: statuses.length,
      reportingPerTrack: trackReportCounts(statuses),
      failing: statuses.filter((entry) => gateState(entry) === 'failing').length,
    });

    return statuses;
  }
}

export const criticalTestsPrometheusService = new CriticalTestsPrometheusService();
