/**
 * Tests Overview Aggregator Service
 *
 * Builds one flat row per service for the tabular /tests page.
 *
 * Two-phase loading — deliberate:
 *   Phase 1 (fast)  getServiceRows()      → summary.json per Allure project (~1 KB each).
 *                                           Gives totals, pass/fail/skip, duration, last run.
 *   Phase 2 (heavy) getSeverityForService() → status-chart.json per project (up to ~3 MB each).
 *                                            Only source of per-severity data, so critical
 *                                            counts stream in after the table is already visible.
 *
 * The service registry below is the single source of truth for which Allure
 * projects belong to which service, mirroring the per-service aggregators in
 * this folder while additionally exposing the raw statistic + duration fields
 * the table needs.
 */

import {
  allureApiService,
  CRITICAL_SEVERITIES,
  emptySeverityMatrix,
  type AllureSeverity,
  type ProjectSeverityBreakdown,
  type SeverityStatusCounts,
} from '../allure';
import { logger } from 'src/utils/logger';

