// ============================================================================
// Row types
// ============================================================================

/** Per-Allure-project statistics inside a service row. */
export interface ServiceSuiteStat {
  name: string;
  displayName: string;
  projectId: string;
  /** false when Allure has no report for this project (404 / empty) */
  hasData: boolean;
  totalTests: number;
  passedTests: number;
  failedTests: number;
  skippedTests: number;
  lastRunAt: Date | null;
  durationMs: number;
  allureUrl: string;
}

/** Loading state of the lazily fetched severity data. */
export type SeverityLoadState = 'pending' | 'loading' | 'loaded' | 'error';

/** One table row. */
export interface ServiceOverviewRow {
  service: string;
  displayName: string;
  group: string;
  groupDisplayName: string;
  groupIcon: string;
  environment: string;

  suites: ServiceSuiteStat[];
  /** true when at least one suite returned a report */
  hasData: boolean;
  suitesWithData: number;

  totalTests: number;
  passedTests: number;
  failedTests: number;
  skippedTests: number;
  /** Percentage of executed (non-skipped) tests that passed, 0–100 */
  passRate: number;

  lastRunAt: Date | null;
  durationMs: number;

  severityState: SeverityLoadState;
  /** blocker + critical */
  criticalTests: number;
  criticalFailed: number;
  criticalSkipped: number;
  blockerTests: number;
  blockerFailed: number;
  bySeverity: Record<AllureSeverity, SeverityStatusCounts>;
}

/** Totals across every row — drives the KPI strip. */
export interface OverviewTotals {
  services: number;
  servicesWithData: number;
  failingServices: number;
  servicesWithCriticalFailures: number;
  totalTests: number;
  failedTests: number;
  skippedTests: number;
  criticalTests: number;
  criticalFailed: number;
  passRate: number;
  severityComplete: boolean;
}

// ============================================================================
// Pure helpers (unit tested)
// ============================================================================

/** Pass rate over executed tests — skipped tests are excluded from the denominator. */
export function computePassRate(passed: number, failed: number): number {
  const executed = passed + failed;
  return executed > 0 ? (passed / executed) * 100 : 0;
}

/** Build an empty row for a service definition, before any Allure data arrives. */
function createEmptyRow(
  definition: ServiceDefinition,
  environment: string
): ServiceOverviewRow {
  const group =
    SERVICE_GROUPS.find((candidate) => candidate.name === definition.group) ||
    SERVICE_GROUPS[0];

  return {
    service: definition.service,
    displayName: definition.displayName,
    group: definition.group,
    groupDisplayName: group.displayName,
    groupIcon: group.icon,
    environment,
    suites: [],
    hasData: false,
    suitesWithData: 0,
    totalTests: 0,
    passedTests: 0,
    failedTests: 0,
    skippedTests: 0,
    passRate: 0,
    lastRunAt: null,
    durationMs: 0,
    severityState: 'pending',
    criticalTests: 0,
    criticalFailed: 0,
    criticalSkipped: 0,
    blockerTests: 0,
    blockerFailed: 0,
    bySeverity: emptySeverityMatrix(),
  };
}

/** Roll suite statistics up into the service row totals. */
export function rollUpSuites(
  row: ServiceOverviewRow,
  suites: ServiceSuiteStat[]
): ServiceOverviewRow {
  const withData = suites.filter((entry) => entry.hasData);

  const lastRunAt = withData.reduce<Date | null>((latest, entry) => {
    if (!entry.lastRunAt) return latest;
    return !latest || entry.lastRunAt > latest ? entry.lastRunAt : latest;
  }, null);

  const passedTests = withData.reduce((sum, entry) => sum + entry.passedTests, 0);
  const failedTests = withData.reduce((sum, entry) => sum + entry.failedTests, 0);

  return {
    ...row,
    suites,
    hasData: withData.length > 0,
    suitesWithData: withData.length,
    totalTests: withData.reduce((sum, entry) => sum + entry.totalTests, 0),
    passedTests,
    failedTests,
    skippedTests: withData.reduce((sum, entry) => sum + entry.skippedTests, 0),
    passRate: computePassRate(passedTests, failedTests),
    lastRunAt,
    // Suites run in parallel in CI, so the slowest suite — not the sum — is the
    // wall-clock cost of the service's test run.
    durationMs: withData.reduce((max, entry) => Math.max(max, entry.durationMs), 0),
  };
}

/** Merge one project's severity matrix into an accumulator matrix. */
export function mergeSeverityMatrices(
  target: Record<AllureSeverity, SeverityStatusCounts>,
  breakdown: ProjectSeverityBreakdown
): Record<AllureSeverity, SeverityStatusCounts> {
  for (const severity of Object.keys(breakdown.bySeverity) as AllureSeverity[]) {
    const source = breakdown.bySeverity[severity];
    const bucket = target[severity];
    bucket.total += source.total;
    bucket.passed += source.passed;
    bucket.failed += source.failed;
    bucket.skipped += source.skipped;
  }
  return target;
}

/** Derive the critical (blocker + critical) figures from a severity matrix. */
export function summarizeSeverity(
  bySeverity: Record<AllureSeverity, SeverityStatusCounts>
): Pick<
  ServiceOverviewRow,
  'criticalTests' | 'criticalFailed' | 'criticalSkipped' | 'blockerTests' | 'blockerFailed'
> {
  const critical = CRITICAL_SEVERITIES.reduce(
    (acc, severity) => {
      acc.total += bySeverity[severity].total;
      acc.failed += bySeverity[severity].failed;
      acc.skipped += bySeverity[severity].skipped;
      return acc;
    },
    { total: 0, failed: 0, skipped: 0 }
  );

  return {
    criticalTests: critical.total,
    criticalFailed: critical.failed,
    criticalSkipped: critical.skipped,
    blockerTests: bySeverity.blocker.total,
    blockerFailed: bySeverity.blocker.failed,
  };
}

/** Aggregate KPI totals over the visible rows. */
export function computeTotals(rows: ServiceOverviewRow[]): OverviewTotals {
  const withData = rows.filter((row) => row.hasData);
  const passedTests = withData.reduce((sum, row) => sum + row.passedTests, 0);
  const failedTests = withData.reduce((sum, row) => sum + row.failedTests, 0);

  return {
    services: rows.length,
    servicesWithData: withData.length,
    failingServices: withData.filter((row) => row.failedTests > 0).length,
    servicesWithCriticalFailures: withData.filter((row) => row.criticalFailed > 0).length,
    totalTests: withData.reduce((sum, row) => sum + row.totalTests, 0),
    failedTests,
    skippedTests: withData.reduce((sum, row) => sum + row.skippedTests, 0),
    criticalTests: withData.reduce((sum, row) => sum + row.criticalTests, 0),
    criticalFailed: withData.reduce((sum, row) => sum + row.criticalFailed, 0),
    passRate: computePassRate(passedTests, failedTests),
    severityComplete:
      withData.length > 0 && withData.every((row) => row.severityState === 'loaded'),
  };
}

// ============================================================================
// Service
// ============================================================================

export class TestsOverviewAggregatorService {
  private readonly logPrefix = '[TestsOverviewAggregator]';

  /**
   * Phase 1 — one row per service from the cheap summary.json widgets.
   *
   * Never rejects: a service whose Allure projects are missing comes back as a
   * row with `hasData: false` so the table can show it as "No data".
   */
  async getServiceRows(environment: string): Promise<ServiceOverviewRow[]> {
    logger.info(`${this.logPrefix} Fetching service rows for environment: ${environment}`);

    const rows = await Promise.all(
      SERVICE_DEFINITIONS.map(async (definition) => {
        const row = createEmptyRow(definition, environment);

        const suites = await Promise.all(
          definition.suites.map((suiteDefinition) =>
            this.fetchSuiteStat(suiteDefinition, environment)
          )
        );

        return rollUpSuites(row, suites);
      })
    );

    logger.info(`${this.logPrefix} Built ${rows.length} service rows`, {
      withData: rows.filter((row) => row.hasData).length,
      failing: rows.filter((row) => row.failedTests > 0).length,
    });

    return rows;
  }

  /**
   * Phase 2 — severity breakdown for a single service.
   *
   * Fetches status-chart.json for every suite that reported data and folds the
   * results into one matrix. Returns null when no suite yielded severity data,
   * which the caller surfaces as `severityState: 'error'`.
   */
  async getSeverityForService(row: ServiceOverviewRow): Promise<{
    bySeverity: Record<AllureSeverity, SeverityStatusCounts>;
    summary: ReturnType<typeof summarizeSeverity>;
  } | null> {
    const projectIds = row.suites
      .filter((entry) => entry.hasData)
      .map((entry) => entry.projectId);

    if (projectIds.length === 0) {
      return null;
    }

    const breakdowns = await Promise.all(
      projectIds.map((projectId) => allureApiService.getSeverityBreakdown(projectId))
    );

    const resolved = breakdowns.filter(
      (breakdown): breakdown is ProjectSeverityBreakdown => breakdown !== null
    );

    if (resolved.length === 0) {
      logger.warn(`${this.logPrefix} No severity data for ${row.service}`);
      return null;
    }

    const bySeverity = resolved.reduce(
      (matrix, breakdown) => mergeSeverityMatrices(matrix, breakdown),
      emptySeverityMatrix()
    );

    return { bySeverity, summary: summarizeSeverity(bySeverity) };
  }

  /** Fetch one Allure project's summary widget and map it to a suite stat. */
  private async fetchSuiteStat(
    suiteDefinition: SuiteDefinition,
    environment: string
  ): Promise<ServiceSuiteStat> {
    const projectId = suiteDefinition.projectId(environment);
    const base: ServiceSuiteStat = {
      name: suiteDefinition.name,
      displayName: suiteDefinition.displayName,
      projectId,
      hasData: false,
      totalTests: 0,
      passedTests: 0,
      failedTests: 0,
      skippedTests: 0,
      lastRunAt: null,
      durationMs: 0,
      allureUrl: allureApiService.getProjectUrl(projectId),
    };

    try {
      const report = await allureApiService.getLatestReport(projectId);
      if (!report || report.statistic.total === 0) {
        return base;
      }

      const { passed, failed, broken, skipped, total } = report.statistic;

      return {
        ...base,
        hasData: true,
        totalTests: total,
        passedTests: passed,
        // Allure's `broken` (errored) tests are failures for our purposes
        failedTests: failed + broken,
        skippedTests: skipped,
        lastRunAt: new Date(report.time.stop),
        durationMs: report.time.duration,
      };
    } catch (error) {
      logger.error(`${this.logPrefix} Error fetching ${projectId}:`, error);
      return base;
    }
  }
}

export const testsOverviewAggregatorService = new TestsOverviewAggregatorService();
