/**
 * Sentinel Log API Service
 *
 * Fetches log trend data from the Sentinel API and transforms it into
 * chart-consumable series keyed by log level.
 *
 * Architecture decision (locked):
 *   Base URL: https://api.sentinel.docbits.com — fixed, NOT env-prefixed.
 *   The Sentinel API is a single multi-tenant service; environment is
 *   passed as the `namespace` query parameter (e.g., 'dev', 'stage', 'prod').
 *   Namespace is derived at call-time from getCurrentEnvironment().
 */

import AbstractApiService from 'src/services/abstractApiService';
import { getCurrentEnvironment } from 'src/pages/APIs';

// ============================================================================
// TypeScript Response Interfaces (matches actual Sentinel API response)
// ============================================================================

/** Aggregate log level counts (totals or trend direction). */
export interface SentinelTotals {
  critical: number;
  error: number;
  warning: number;
}

/** A single hourly data point in the trend array. */
export interface SentinelHourlyPoint {
  timestamp: string;
  critical: number;
  error: number;
  warning: number;
}

/** Full response shape from GET https://api.sentinel.docbits.com/api/logs/trends */
export interface SentinelLogTrendsResponse {
  totals: SentinelTotals;
  trend: SentinelTotals;        // aggregate trend direction counts
  timeseries: SentinelHourlyPoint[];
  app_namespaces: string[];
  granularity: string;
  period_hours: number;
}

// ============================================================================
// Chart-Consumable Output Type
// ============================================================================

/** Chart-ready data point produced by the transformer. */
export interface LogChartDataPoint {
  timestamp: string;
  critical: number;
  error: number;
  warning: number;
}

// ============================================================================
// Transformer
// ============================================================================

/**
 * Transform an hourly array into chart-consumable data points.
 * Each input point maps 1-to-1 to an output point; no aggregation is applied.
 */
export function transformHourlyToLogChartData(
  hourly: SentinelHourlyPoint[]
): LogChartDataPoint[] {
  return hourly.map((point) => ({
    timestamp: point.timestamp,
    critical: point.critical,
    error: point.error,
    warning: point.warning,
  }));
}

// ============================================================================
// Log Count Point (for single-level series)
// ============================================================================

/**
 * A single log level's count at a given timestamp.
 * Used as the SeverityPanel logData prop shape.
 */
export interface LogCountPoint {
  timestamp: string;
  count: number;
}

/**
 * Extract a single log level's count series from LogChartDataPoint[].
 * Used to bridge LogChartDataPoint[] to the SeverityPanel logData prop shape.
 */
export function transformLogLevelToCountSeries(
  points: LogChartDataPoint[],
  level: 'critical' | 'error' | 'warning'
): LogCountPoint[] {
  return points.map((p) => ({ timestamp: p.timestamp, count: p[level] }));
}

// ============================================================================
// Service Class
// ============================================================================

export class SentinelLogApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  /**
   * Fetch log trend data from Sentinel API.
   * Calls GET https://api.sentinel.docbits.com/api/logs/trends?namespace={ns}&hours={hours}&granularity=hourly
   * Namespace is derived from getCurrentEnvironment() (e.g., 'dev', 'stage', 'prod').
   * Fixed base URL (not env-prefixed) per architecture decision.
   */
  public async getLogTrends(hours: number = 168): Promise<SentinelLogTrendsResponse> {
    const namespace = getCurrentEnvironment();
    const params = new URLSearchParams({
      namespace,
      hours: String(hours),
      granularity: 'hourly',
    });
    const endpoint = `https://api.sentinel.docbits.com/api/logs/trends?${params}`;
    return await this.getWithoutOrgId<SentinelLogTrendsResponse>(endpoint);
  }
}

