/**
 * Generic Tests Aggregator Service Factory
 *
 * Creates aggregator services for any service that follows the standard
 * Allure project naming pattern: {projectPrefix}-{environment}
 *
 * Used to avoid duplicating nearly identical aggregator services for each service.
 */

import { allureApiService } from '../allure';
import { logger } from 'src/utils/logger';
import type { TestCategoryStatus } from './webTestsAggregator.service';

/**
 * Service configuration for creating an aggregator
 */
export interface ServiceConfig {
  /** Service identifier used in URLs and routing (e.g., 'auth', 'extraction') */
  serviceId: string;
  /** Human-readable display name (e.g., 'Auth Service', 'Extraction Service') */
  displayName: string;
  /** Allure project prefix (e.g., 'auth', 'extraction') - combined with env to form project ID */
  projectPrefix: string;
}

/**
 * Generic service test status
 */
export interface GenericTestsStatus {
  service: string;
  displayName: string;
  environment: string;
  allPassing: boolean;
  categories: TestCategoryStatus[];
  totalTests: number;
  totalFailed: number;
  lastUpdated: Date;
}

/**
 * Generic service that aggregates test results from Allure
 */
export class GenericTestsAggregatorService {
  private config: ServiceConfig;
  private logPrefix: string;

  constructor(config: ServiceConfig) {
    this.config = config;
    this.logPrefix = `[${config.displayName}TestsAggregator]`;
  }

  /**
   * Get test status for this service in current environment
   *
   * @param environment - Current environment (dev, stage, prod, etc.)
   * @returns GenericTestsStatus object with test status
   */
  async getTestsStatus(environment: string): Promise<GenericTestsStatus> {
    logger.info(`${this.logPrefix} Fetching test status for environment: ${environment}`);

    const categories: TestCategoryStatus[] = [];
    const projectId = `${this.config.projectPrefix}-${environment}`;

    try {
      const report = await allureApiService.getLatestReport(projectId);

      const status: TestCategoryStatus = {
        name: 'all',
        displayName: 'All Tests',
        projectId,
        allPassing: report
          ? report.statistic.failed + report.statistic.broken === 0
          : false,
        totalTests: report?.statistic.total || 0,
        failedTests: report ? report.statistic.failed + report.statistic.broken : 0,
        lastRunAt: report ? new Date(report.time.stop) : null,
      };

      logger.debug(`${this.logPrefix} All Tests:`, {
        allPassing: status.allPassing,
        totalTests: status.totalTests,
        failedTests: status.failedTests,
      });

      categories.push(status);
    } catch (error) {
      logger.error(`${this.logPrefix} Error fetching tests:`, error);

      categories.push({
        name: 'all',
        displayName: 'All Tests',
        projectId,
        allPassing: false,
        totalTests: 0,
        failedTests: 0,
        lastRunAt: null,
      });
    }

    const allPassing = categories.every((cat) => cat.allPassing);
    const totalTests = categories.reduce((sum, cat) => sum + cat.totalTests, 0);
    const totalFailed = categories.reduce((sum, cat) => sum + cat.failedTests, 0);

    logger.info(`${this.logPrefix} Aggregated status for ${environment}:`, {
      allPassing,
      totalTests,
      totalFailed,
    });

    return {
      service: this.config.serviceId,
      displayName: this.config.displayName,
      environment,
      allPassing,
      categories,
      totalTests,
      totalFailed,
      lastUpdated: new Date(),
    };
  }

  /**
   * Get status for a specific test category
   */
  async getCategoryStatus(
    environment: string,
    categoryName: string
  ): Promise<TestCategoryStatus | null> {
    const fullStatus = await this.getTestsStatus(environment);
    return fullStatus.categories.find((cat) => cat.name === categoryName) || null;
  }
}

